pub(crate) fn command_line(executable: &Path, arguments: &[String]) -> Result<Vec<u16>> {
    let mut command = quote_argument(&executable.as_os_str().to_string_lossy());
    for argument in arguments {
        command.push(' ');
        command.push_str(&quote_argument(argument));
    }
    wide_nul(OsStr::new(&command))
}

fn quote_argument(argument: &str) -> String {
    if !argument.is_empty()
        && !argument
            .chars()
            .any(|value| value.is_whitespace() || value == '"')
    {
        return argument.to_owned();
    }
    let mut output = String::from('"');
    let mut slashes = 0usize;
    for character in argument.chars() {
        match character {
            '\\' => slashes += 1,
            '"' => {
                output.push_str(&"\\".repeat(slashes * 2 + 1));
                output.push('"');
                slashes = 0;
            }
            _ => {
                output.push_str(&"\\".repeat(slashes));
                output.push(character);
                slashes = 0;
            }
        }
    }
    output.push_str(&"\\".repeat(slashes * 2));
    output.push('"');
    output
}

pub(crate) fn environment_block(environment: &BTreeMap<String, String>) -> Result<Vec<u16>> {
    let mut block = Vec::new();
    for (key, value) in environment {
        block.extend(OsStr::new(&format!("{key}={value}")).encode_wide());
        block.push(0);
    }
    block.push(0);
    if block.len() == 1 {
        block.push(0);
    }
    Ok(block)
}

pub(crate) fn wide_nul(value: &OsStr) -> Result<Vec<u16>> {
    let mut wide = value.encode_wide().collect::<Vec<_>>();
    if wide.contains(&0) {
        bail!("foreign-process Windows argument contains NUL");
    }
    wide.push(0);
    Ok(wide)
}

