struct SuspendedProcess {
    process: Handle,
    thread: Handle,
    process_id: u32,
}

impl SuspendedProcess {
    fn resume(&mut self) -> Result<u32> {
        let count = unsafe { ResumeThread(self.thread.as_handle()) };
        if count == u32::MAX {
            return Err(last_error("foreign-process child could not be resumed"));
        }
        Ok(count)
    }

    fn exit_code(&self) -> Result<u32> {
        let mut code = 0u32;
        if unsafe { GetExitCodeProcess(self.process.as_handle(), &mut code) } == 0 {
            return Err(last_error("foreign-process child exit code is unavailable"));
        }
        Ok(code)
    }

    fn terminate(&mut self) {
        if !self.process.is_invalid() {
            unsafe { TerminateProcess(self.process.as_handle(), TERMINATED_EXIT_CODE) };
            unsafe { WaitForSingleObject(self.process.as_handle(), 5000) };
        }
    }
}

fn last_error(context: &'static str) -> anyhow::Error {
    anyhow::Error::new(std::io::Error::last_os_error()).context(context)
}

